            valid_moves.append((dx, dy))
    if not valid_moves:
        return [0, 0]
    if not resources:
        tx, ty = w // 2, h // 2
        best = min(valid_moves, key=lambda d: cheb(sx + d[0], sy + d[1], tx, ty))
        return [best[0], best[1]]

    near_end = 1 if remaining_resource_count <= 4 or turns_remaining <= 6 else 0

    def best_target_for(nsx, nsy):
        best_val = None
        best_cell = None
